// Divider insert (open lattice, no floor) for sample storage box
// Print orientation: standing on bed, walls build upward in +Z

// ---------------- Parameters ----------------
outer_x   = 58.8;   // outside size along X (mm)
outer_y   = 97.2;   // outside size along Y (mm)
height    = 25;     // wall height (mm)
wall      = 1.2;    // thickness of all walls, outer and inner (mm)
cells_x   = 2;      // number of cells along X
cells_y   = 5;      // number of cells along Y
cell      = 18;     // inside size of each square cell (mm)
eps       = 0.5;    // cutter overshoot past faces (mm)

$fn = 64;

// Check: 3*18 + 4*1.2 = 58.8 ; 5*18 + 6*1.2 = 97.2

// ---------------- Model ----------------
difference() {
    // Solid outer block, centred in X/Y, sitting on z = 0
    translate([-outer_x/2, -outer_y/2, 0])
        cube([outer_x, outer_y, height]);

    // Cut out the grid of open cells (through full height, no floor)
    for (i = [0 : cells_x - 1])
        for (j = [0 : cells_y - 1])
            translate([-outer_x/2 + wall + i*(cell + wall),
                       -outer_y/2 + wall + j*(cell + wall),
                       -eps])
                cube([cell, cell, height + 2*eps]);
}
```

