// Glassware drying board: base plate with a 6 x 4 grid of vertical pegs
// Units: mm. Print orientation: base plate flat on bed, pegs pointing up (+Z).

// ---------------- Parameters ----------------
plate_x      = 155;   // base plate length along X
plate_y      = 105;   // base plate width along Y
plate_t      = 4;     // base plate thickness (z = 0 to 4)

peg_d        = 10;    // peg diameter
peg_top_z    = 54;    // top of pegs (absolute Z)
peg_h        = peg_top_z - plate_t; // peg height above plate (50 mm)

peg_nx       = 7;     // number of pegs along X
peg_ny       = 4;     // number of pegs along Y
peg_pitch    = 25;    // centre-to-centre spacing (both X and Y)

overlap      = 0.01;  // small overlap so pegs fuse into the plate

$fn          = 64;    // curve resolution

// Derived: grid offsets so the peg grid is centred on the plate
grid_x0 = -(peg_nx - 1) * peg_pitch / 2;  // -62.5
grid_y0 = -(peg_ny - 1) * peg_pitch / 2;  // -37.5

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_x / 2, -plate_y / 2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Peg grid
    for (i = [0 : peg_nx - 1])
        for (j = [0 : peg_ny - 1])
            translate([grid_x0 + i * peg_pitch,
                       grid_y0 + j * peg_pitch,
                       plate_t - overlap])
                cylinder(d = peg_d, h = peg_h + overlap, $fn = 64);
}
```

