// Adjustable shim plate with two rounded-end bolt slots
// Print orientation: flat on bed, z = 0 to plate_t

$fn = 64;

// --- Plate dimensions ---
plate_l = 70;    // length along X
plate_w = 24;    // width along Y
plate_t = 2;     // thickness along Z

// --- Slot dimensions ---
slot_w   = 2.89;  // slot width (= end radius * 2)
slot_l   = 16;   // slot overall length, end to end
slot_xs  = [-15, 15]; // slot centre X positions
slot_y   = 0;    // slot centre Y position

// --- Cut clearance ---
eps = 0.5;       // extension past faces for clean cuts

// Rounded-end slot (stadium), centred at origin, running along X
module slot2d(len, wid) {
    hull() {
        for (s = [-1, 1])
            translate([s * (len - wid) / 2, 0]) circle(d = wid);
    }
}

difference() {
    // Plate
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Through-slots
    for (x = slot_xs)
        translate([x, slot_y, -eps])
            linear_extrude(height = plate_t + 2 * eps)
                slot2d(slot_l, slot_w);
}
