// Flat spacer ring - raises an instrument off the bench
// Print orientation: flat on the bed, centred on the origin

// ---------------- Parameters (mm) ----------------
ring_thickness   = 3;     // ring height (Z)
outer_diameter   = 90;    // ring outer diameter
inner_diameter   = 62;    // ring inner (bore) diameter
hole_diameter    = 3.4;   // mounting through-hole diameter
hole_count       = 8;     // number of mounting holes
hole_pcd         = 57;    // pitch circle diameter of the holes
hole_start_angle = 0;     // first hole on +X axis (degrees)
cut_extra        = 0.5;   // cutter overshoot past faces
$fn              = 128;   // curve resolution

// ---------------- Model ----------------
difference() {
    // Solid disc
    cylinder(h = ring_thickness, d = outer_diameter);

    // Central bore
    translate([0, 0, -cut_extra])
        cylinder(h = ring_thickness + 2 * cut_extra, d = inner_diameter);

    // Mounting through-holes on the pitch circle
    for (i = [0 : hole_count - 1]) {
        rotate([0, 0, hole_start_angle + i * 360 / hole_count])
            translate([hole_pcd / 2, 0, -cut_extra])
                cylinder(h = ring_thickness + 2 * cut_extra, d = hole_diameter, $fn = 64);
    }
}
