// Microplate riser
// Units: mm. Prints upright: legs on the bed (z = 0), top plate at the top.

// ---- Top plate ----
plate_x     = 130;   // plate length (X)
plate_y     = 95;    // plate width (Y)
plate_t     = 6;     // plate thickness
plate_top_z = 40;    // z of the plate's top face

// ---- Legs ----
leg_size    = 12;    // square leg side (X and Y)

// ---- Central window ----
win_x       = 96;    // window length (X)
win_y       = 61;    // window width (Y)

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces

// Derived
plate_bot_z = plate_top_z - plate_t;   // underside of plate (z = 34)
leg_h       = plate_bot_z;             // legs run z = 0 to underside

union() {
    // Top plate with central window
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bot_z])
            cube([plate_x, plate_y, plate_t]);
        translate([-win_x/2, -win_y/2, plate_bot_z - eps])
            cube([win_x, win_y, plate_t + 2*eps]);
    }

    // Four corner legs, flush with the plate's outer edges
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
                   sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
                   0])
            // extend slightly into the plate so legs fuse with it
            cube([leg_size, leg_size, leg_h + 0.01]);
}
```

