// Divider insert for sample storage box - open lattice, no floor
// Units: mm

outer_x   = 194;   // outside length (X)
outer_y   = 66;    // outside width (Y)
height    = 30;    // wall height (Z)
wall      = 2;     // thickness of all walls, outer and inner
cells_x   = 5;     // number of cells along X
cells_y   = 2;     // number of cells along Y
cell      = 30;    // inside size of each square cell
eps       = 0.5;   // cutter overshoot past top/bottom faces

// Check: 6*30 + 7*2 = 194 ; 2*30 + 3*2 = 66

pitch = cell + wall;   // centre-to-centre spacing of cells

difference() {
    // Solid outer block, centred in XY, resting on z = 0
    translate([-outer_x/2, -outer_y/2, 0])
        cube([outer_x, outer_y, height]);

    // Through-cut every cell (no floor)
    for (i = [0 : cells_x - 1])
        for (j = [0 : cells_y - 1])
            translate([-outer_x/2 + wall + i*pitch,
                       -outer_y/2 + wall + j*pitch,
                       -eps])
                cube([cell, cell, height + 2*eps]);
}
