// Divider insert for sample storage box: open 5x5 lattice with no floor
// Print orientation: stands on the bed (z = 0), centred on the origin in X and Y

$fn = 64;

// ---------------- Parameters ----------------
outer_x   = 137;   // outer wall size along X (mm)
outer_y   = 82;   // outer wall size along Y (mm)
height    = 25;    // wall height (mm)
wall      = 2;     // thickness of all walls, outer and inner (mm)
cells_x   = 5;     // number of cells along X
cells_y   = 5;     // number of cells along Y
cell      = 25;    // inside size of each square cell (mm)
overcut   = 0.5;   // extra cutter length past the top and bottom faces (mm)

// Derived values
pitch   = cell + wall;     // centre-to-centre spacing of cells (mm)
x0      = -outer_x / 2;    // left edge of the part
y0      = -outer_y / 2;    // front edge of the part

// Check: cells * cell + (cells + 1) * wall = 5*25 + 6*2 = 137 mm
echo(fit_x = cells_x * cell + (cells_x + 1) * wall);
echo(fit_y = cells_y * cell + (cells_y + 1) * wall);

// ---------------- Model ----------------
difference() {
    // Solid block that becomes the outer wall and internal walls
    translate([x0, y0, 0])
        cube([outer_x, outer_y, height]);

    // Through-cut every cell, top to bottom (no floor)
    for (i = [0 : cells_x - 1])
        for (j = [0 : cells_y - 1])
            translate([x0 + wall + i * pitch,
                       y0 + wall + j * pitch,
                       -overcut])
                cube([cell, cell, height + 2 * overcut]);
}
