// Wall mounting strip with countersunk screw holes
// Print orientation: flat on bed, countersinks facing up (+Z)

$fn = 96;

// ---- Bar dimensions ----
bar_length = 82;   // X length
bar_width  = 24;    // Y width
bar_thick  = 6;     // Z thickness

// ---- Screw holes ----
hole_count   = 4;     // number of holes
hole_pitch   = 30;    // centre-to-centre spacing along X
hole_d       = 5.5;   // through-hole diameter
csk_d        = 11;    // countersink diameter at top surface
csk_angle    = 90;    // countersink included angle (degrees)

// ---- Derived ----
csk_depth = (csk_d - hole_d) / 2 / tan(csk_angle / 2);  // cone depth (2.75 mm for 90 deg)
overcut   = 0.5;                                         // extension past faces
csk_top_d = csk_d + 2 * overcut * tan(csk_angle / 2);    // cone diameter at overcut height

module countersunk_hole() {
    // through-hole
    translate([0, 0, -overcut])
        cylinder(d = hole_d, h = bar_thick + 2 * overcut);
    // 90-degree countersink cone, extended above the top face
    translate([0, 0, bar_thick - csk_depth])
        cylinder(d1 = hole_d, d2 = csk_top_d, h = csk_depth + overcut);
}

difference() {
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thick]);

    for (i = [0 : hole_count - 1])
        translate([(i - (hole_count - 1) / 2) * hole_pitch, 0, 0])
            countersunk_hole();
}
```

