// Glassware drying board: base plate with a 3 x 2 grid of vertical pegs
// Print orientation: plate flat on the bed, pegs pointing up (+Z)

// ---------------- Parameters ----------------
plate_x      = 100;  // base plate length along X (mm)
plate_y      = 60;   // base plate width along Y (mm)
plate_t      = 4;    // base plate thickness (mm), z = 0 to 4

peg_d        = 10;   // peg diameter (mm)
peg_top_z    = 34;   // peg top height (mm), pegs rise from z = 4 to z = 34
peg_count_x  = 3;    // number of pegs along X
peg_count_y  = 2;    // number of pegs along Y
peg_pitch    = 64;   // centre-to-centre peg spacing in X and Y (mm)

overlap      = 0.01; // small overlap so pegs fuse into the plate (mm)

$fn = 96;            // curve resolution

// ---------------- Derived ----------------
peg_h = peg_top_z - plate_t;                     // visible peg height (30 mm)
x0 = -(peg_count_x - 1) * peg_pitch / 2;         // first peg X (grid centred)
y0 = -(peg_count_y - 1) * peg_pitch / 2;         // first peg Y (grid centred)

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, sitting on z = 0
    translate([-plate_x / 2, -plate_y / 2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Peg grid
    for (i = [0 : peg_count_x - 1])
        for (j = [0 : peg_count_y - 1])
            translate([x0 + i * peg_pitch, y0 + j * peg_pitch, plate_t - overlap])
                cylinder(d = peg_d, h = peg_h + overlap);
}
