// Hex key organiser block

// Block dimensions
block_l = 52;     // length along X
block_w = 20;     // width along Y
block_h = 24;     // height along Z

// Pockets
pocket_depth   = 15;                    // depth from top face
pocket_pitch   = 10;                    // centre-to-centre spacing along X
pocket_flats   = [2.4, 2.9, 3.4, 4.4];  // across-flats sizes, -X to +X
pocket_count   = len(pocket_flats);
eps            = 0.5;                   // overshoot past top face

// Hexagon circumradius from across-flats size
function hex_r(af) = af / (2 * cos(30));

difference() {
    // Main block, centred in X/Y, sitting on z = 0
    translate([-block_l/2, -block_w/2, 0])
        cube([block_l, block_w, block_h]);

    // Hexagonal pockets along X axis (y = 0)
    for (i = [0 : pocket_count - 1]) {
        x = (i - (pocket_count - 1)/2) * pocket_pitch;
        // $fn = 6 puts vertices on the X axis, so two flats are parallel to X
        translate([x, 0, block_h - pocket_depth])
            cylinder(r = hex_r(pocket_flats[i]),
                     h = pocket_depth + eps,
                     $fn = 6);
    }
}
