module slot(len, wid, h) {
    // stadium shape: centre-to-centre distance = len - wid
    hull() {
        for (s = [-1, 1])
            translate([s * (len - wid) / 2, 0, 0])
                cylinder(d = wid, h = h, $fn = 64);
    }
}

difference() {
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    for (x = slot_x)
        translate([x, slot_y, -eps])
            slot(slot_l, slot_w, plate_t + 2 * eps);
}
