// Flat spacer ring with bolt-circle holes
// Units: mm

$fn = 128;

// --- Ring dimensions ---
ring_thickness = 4;     // ring height (Z)
outer_d        = 90;    // outer diameter
inner_d        = 60;    // inner diameter (bore)

// --- Through-holes ---
hole_count     = 8;     // number of holes
hole_d         = 5.5;   // hole diameter
bolt_circle_d  = 45;    // diameter of the circle the hole centres lie on
start_angle    = 0;     // first hole on +X axis

// --- Boolean overlap ---
eps            = 0.5;   // cutter extension past faces

difference() {
    // Solid disc
    cylinder(d = outer_d, h = ring_thickness);

    // Central bore
    translate([0, 0, -eps])
        cylinder(d = inner_d, h = ring_thickness + 2 * eps);

    // Bolt-circle holes
    for (i = [0 : hole_count - 1]) {
        a = start_angle + i * 360 / hole_count;
        translate([bolt_circle_d / 2 * cos(a), bolt_circle_d / 2 * sin(a), -eps])
            cylinder(d = hole_d, h = ring_thickness + 2 * eps, $fn = 64);
    }
}
