// Microplate riser
// Units: mm. Print orientation: legs down on XY plane, top plate up.

// ---------- Parameters ----------
plate_x      = 130;   // top plate length (X)
plate_y      = 100;   // top plate width (Y)
plate_t      = 5;     // top plate thickness
top_z        = 30;    // z of top face of plate
leg_size     = 12;    // square leg cross-section (X and Y)
window_x     = 86;    // central window length (X)
window_y     = 56;    // central window width (Y)
eps          = 0.5;   // cutter overshoot

plate_bot_z  = top_z - plate_t;   // underside of plate (26)
leg_h        = plate_bot_z;       // legs run z=0 to plate underside

$fn = 64;

// ---------- Model ----------
union() {
    // Top plate with central window
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bot_z])
            cube([plate_x, plate_y, plate_t]);
        translate([-window_x/2, -window_y/2, plate_bot_z - eps])
            cube([window_x, window_y, plate_t + 2*eps]);
    }

    // Four corner legs, flush with plate outer edges
    // Legs extend 0.01 mm into the plate so they fuse into one solid
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
                   sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
                   0])
            cube([leg_size, leg_size, leg_h + 0.01]);
}
```

