// Diffuser sheet frame for lab light pad
// Print flat on the bed, centred on origin.

$fn = 64;

// --- Dimensions (mm) ---
frame_x      = 140;   // outer size in X
frame_y      = 90;    // outer size in Y
frame_t      = 3;     // frame thickness (Z)
window_x     = 124;   // window size in X
window_y     = 74;    // window size in Y
hole_d       = 3.4;   // corner through-hole diameter
hole_x       = 66;    // hole centre offset from origin in X (±)
hole_y       = 41;    // hole centre offset from origin in Y (±)
eps          = 0.5;   // cutter overshoot past faces

difference() {
