bore_x       = 0;     // bore axis X position (mm)
bore_z       = 10;    // bore axis height (mm)

mount_d      = 3.4;   // vertical mounting hole diameter (mm)
mount_x      = 9;     // mounting hole X offset from centre, used as +/- (mm)
mount_y      = 0;     // mounting hole Y position (mm)

eps          = 0.5;   // extra cutter length past each face (mm)
$fn          = 96;    // circle resolution

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_z]);

    // Horizontal bore through the block along Y
    translate([bore_x, -block_y/2 - eps, bore_z])
        rotate([-90, 0, 0])
            cylinder(d = bore_d, h = block_y + 2*eps);

