// Base plate
plate_x = 104;      // plate length in X
plate_y = 104;      // plate length in Y
plate_t = 4;        // plate thickness (z = 0 to 4)

// Pegs
peg_d      = 6;     // peg diameter
peg_top_z  = 34;    // top of pegs (absolute z)
peg_pitch  = 40;    // centre-to-centre spacing in X and Y
peg_nx     = 3;     // pegs along X
peg_ny     = 3;     // pegs along Y
overlap    = 0.01;  // pegs sink into plate for a clean union

$fn = 64;

union() {
    // Base plate, centred on origin in X/Y
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // 3 x 3 peg grid, centred on plate
    for (i = [0 : peg_nx - 1])
        for (j = [0 : peg_ny - 1])
            translate([(i - (peg_nx - 1)/2) * peg_pitch,
                       (j - (peg_ny - 1)/2) * peg_pitch,
                       plate_t - overlap])
                cylinder(d = peg_d, h = peg_top_z - plate_t + overlap);
}
