    union() {
        cube([leg, w, t]);                                     // horizontal leg
        cube([t, w, leg]);                                     // vertical leg
        translate([t, 0, t]) difference() {                    // concave fillet at the inner corner
            cube([fillet, w, fillet]);
            translate([fillet, 0, fillet]) rotate([-90, 0, 0]) cylinder(h = w, r = fillet);
