notch_d   = 14;   // notch depth into plate (along -Y)
notch_p   = 15;   // notch centre-to-centre spacing (X)

eps       = 0.5;  // cutter overshoot past faces

$fn = 64;

difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_l/2, -plate_w/2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Notches along +Y edge, centred along X
    for (i = [0 : notch_n - 1]) {
        x = (i - (notch_n - 1)/2) * notch_p;
        translate([x - notch_w/2, plate_w/2 - notch_d, -eps])
            cube([notch_w, notch_d + eps, plate_t + 2*eps]);
    }
}
