    cylinder(d = disc_d, h = disc_h, $fn = fn * 2);

    // Magnet pockets in top face, first on +X axis
    for (i = [0 : pocket_count - 1])
        rotate([0, 0, i * 360 / pocket_count])
            translate([pocket_circle_d / 2, 0, disc_h - pocket_depth])
                cylinder(d = pocket_d, h = pocket_depth + eps, $fn = fn);

