// Hex key organiser block
// Print orientation: block stands on z = 0, pockets open at the top face

// ---------- Block dimensions ----------
block_len   = 42;    // block length along X (mm)
block_wid   = 18;    // block width along Y (mm)
block_hgt   = 20;    // block height along Z (mm)

// ---------- Pocket parameters ----------
pocket_depth = 15;                        // pocket depth from top face (mm)
pocket_pitch = 12;                        // centre-to-centre spacing along X (mm)
pocket_af    = [2.4, 2.9, 3.4, 4.4, 5.4]; // hex sizes across flats, -X to +X (mm)
n_pockets    = len(pocket_af);            // number of pockets

overcut = 0.5;       // extension of cutters past the top face (mm)

// Circumradius of a hexagon from its across-flats size
function hex_r(af) = af / sqrt(3);

difference() {
    // Main block, centred in X and Y, base on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_hgt]);

    // Hexagonal pockets along y = 0, centred on the block
    for (i = [0 : n_pockets - 1]) {
        x = (i - (n_pockets - 1)/2) * pocket_pitch;
        // cylinder with $fn = 6 places a vertex on +X,
        // so two flats are parallel to the X axis
        translate([x, 0, block_hgt - pocket_depth])
            cylinder(r = hex_r(pocket_af[i]),
                     h = pocket_depth + overcut,
                     $fn = 6);
    }
}
```

