// Flat hex-cap wrench for reagent bottles
// Print orientation: flat on bed, z = 0 to plate_t

// ---------- Parameters ----------
plate_t      = 4;     // plate thickness (Z)
head_d       = 50;    // round head diameter, centred on origin
handle_w     = 18;    // handle width (Y), centred on y = 0
handle_x0    = 0;     // handle start (X)
handle_x1    = 100;   // handle end (X)
hex_af       = 30;    // hex hole size across flats
cut_extra    = 0.5;   // cutter overshoot past faces

hex_r = (hex_af / 2) / cos(30);   // hex circumradius from across-flats

$fn = 128;

// ---------- Model ----------
difference() {
    // Head + handle body
    union() {
        cylinder(d = head_d, h = plate_t, $fn = 128);
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, plate_t]);
    }

    // Hexagonal hole: circle($fn=6) has vertices on the X axis,
    // so two flats lie parallel to the X axis (at y = +/- hex_af/2)
    translate([0, 0, -cut_extra])
        linear_extrude(height = plate_t + 2 * cut_extra)
            circle(r = hex_r, $fn = 6);
}
