// Magnet carrier disc for rotating sample mixer
// Units: mm. Print orientation: flat on bed, pockets facing up.

// ---------------- Parameters ----------------
disc_d          = 50;    // disc outer diameter
disc_h          = 6;     // disc height
pocket_d        = 10.2;  // magnet pocket diameter
pocket_depth    = 3;     // magnet pocket depth (from top face)
pocket_count    = 2;     // number of magnet pockets
pocket_circle_d = 29.8;  // pitch circle diameter of pocket centres
shaft_d         = 6;     // central motor shaft hole diameter
eps             = 0.5;   // overcut so cutters pass through faces
fn_curve        = 128;   // facet count for curved surfaces

// ---------------- Model ----------------
difference() {
    // Main disc
    cylinder(d = disc_d, h = disc_h, $fn = fn_curve);

    // Magnet pockets cut into top face, first on +X axis
    for (i = [0 : pocket_count - 1])
        rotate([0, 0, i * 360 / pocket_count])
            translate([pocket_circle_d / 2, 0, disc_h - pocket_depth])
                cylinder(d = pocket_d, h = pocket_depth + eps, $fn = fn_curve);

    // Central through-hole for motor shaft
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = disc_h + 2 * eps, $fn = fn_curve);
}
