// Adjustable shim plate with two rounded-end bolt slots
// Print orientation: flat on the bed, z = 0 to plate_t

// ---------------- Parameters ----------------
plate_l   = 80;    // plate length along X (mm)
plate_w   = 28;    // plate width along Y (mm)
plate_t   = 3;     // plate thickness along Z (mm)

slot_w    = 5.5;   // slot width (mm) = end radius * 2
slot_l    = 18;    // slot overall length, end to end (mm)
slot_xs   = [-20, 20]; // slot centre X positions (mm)
slot_y    = 0;     // slot centre Y position (mm)

eps       = 0.5;   // cutter overshoot past top/bottom faces (mm)
$fn       = 96;    // facet count for round features

// Derived
slot_r    = slot_w / 2;           // end radius
slot_c2c  = slot_l - slot_w;      // distance between end-arc centres

// ---------------- Modules ----------------
module slot_cutter() {
    // Stadium-shaped slot running along X, extended past both faces
    translate([0, 0, -eps])
        hull() {
            for (sx = [-slot_c2c / 2, slot_c2c / 2])
                translate([sx, 0, 0])
                    cylinder(r = slot_r, h = plate_t + 2 * eps);
        }
}

// ---------------- Part ----------------
difference() {
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    for (x = slot_xs)
        translate([x, slot_y, 0])
            slot_cutter();
}
