// Microplate riser
// Print orientation: legs down on the bed, top plate at z = 26..30

// ---------- Dimensions (mm) ----------
plate_x      = 140;   // top plate length (X)
plate_y      = 90;    // top plate width (Y)
plate_t      = 4;     // top plate thickness
top_z        = 26;    // height of top face of plate
leg_size     = 15;    // square leg side length
window_x     = 90;    // central window length (X)
window_y     = 50;    // central window width (Y)
eps          = 0.5;   // cutter overshoot past faces

// ---------- Derived ----------
plate_bot_z  = top_z - plate_t;   // underside of plate (leg height)
leg_h        = plate_bot_z;

// ---------- Model ----------
union() {
    // Top plate with central window
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bot_z])
            cube([plate_x, plate_y, plate_t]);
        translate([-window_x/2, -window_y/2, plate_bot_z - eps])
            cube([window_x, window_y, plate_t + 2*eps]);
    }

    // Four corner legs, flush with plate outer edges
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
                   sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
                   0])
            // extend slightly into the plate so the union fuses cleanly
            cube([leg_size, leg_size, leg_h + 0.01]);
    }
}
