// Flat spacer ring - raises an instrument off the bench
// Prints flat on the bed, centred on the origin

// ---------- Dimensions (mm) ----------
ring_thickness   = 5;     // height of the annulus (Z)
outer_diameter   = 70;    // outer diameter of the ring
inner_diameter   = 62;    // inner diameter (central opening)
hole_diameter    = 5.5;   // through-hole diameter
hole_count       = 3;     // number of through-holes
hole_pcd         = 58;    // pitch-circle diameter for the holes
first_hole_angle = 0;     // first hole on +X axis (degrees)

// ---------- Modelling parameters ----------
eps    = 0.5;   // overshoot for clean boolean cuts
$fn    = 128;   // facet count for curved surfaces

// ---------- Model ----------
difference() {
    // Main ring body
    cylinder(d = outer_diameter, h = ring_thickness);

    // Central opening
    translate([0, 0, -eps])
        cylinder(d = inner_diameter, h = ring_thickness + 2 * eps);

    // Evenly spaced through-holes on the pitch circle
    for (i = [0 : hole_count - 1]) {
        rotate([0, 0, first_hole_angle + i * 360 / hole_count])
            translate([hole_pcd / 2, 0, -eps])
                cylinder(d = hole_diameter, h = ring_thickness + 2 * eps, $fn = 64);
    }
}
