```openscad
// Microplate riser
// Print orientation: legs on the bed (z = 0), top plate at the top.

// ---------- Dimensions ----------
plate_x      = 140;   // top plate length (X)
plate_y      = 95;    // top plate width (Y)
plate_t      = 5;     // top plate thickness
plate_top_z  = 68;    // z of top face of plate
leg_size     = 10;    // square leg side length
window_x     = 100;   // central window length (X)
window_y     = 55;    // central window width (Y)
eps          = 0.5;   // cutter overshoot

plate_bot_z  = plate_top_z - plate_t;   // underside of plate (z = 45)
leg_h        = plate_bot_z;             // legs run from z = 0 to underside

$fn = 64;

// ---------- Model ----------
union() {
    // Top plate with central window
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bot_z])
            cube([plate_x, plate_y, plate_t]);
        translate([-window_x/2, -window_y/2, plate_bot_z - eps])
            cube([window_x, window_y, plate_t + 2*eps]);
    }

    // Four corner legs, flush with plate outer edges
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
                   sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
                   0])
            cube([leg_size, leg_size, leg_h + 0.01]); // tiny overlap fuses legs to plate
}
