// Magnet carrier disc for rotating sample mixer
// Print orientation: flat on bed, pockets facing up

// ---- Disc ----
disc_d        = 40;     // disc outer diameter
disc_h        = 6;      // disc height

// ---- Magnet pockets ----
mag_count     = 2;      // number of magnet pockets
mag_d         = 8.2;    // pocket diameter
mag_depth     = 5;      // pocket depth from top face
mag_circle_d  = 23.8;   // pitch circle diameter for pocket centres
mag_start_ang = 0;      // first pocket on +X axis (degrees)

// ---- Shaft hole ----
shaft_d       = 4;      // central motor shaft hole diameter

// ---- Misc ----
eps           = 0.5;    // overshoot for clean boolean cuts
$fn           = 96;     // curve resolution

difference() {
    // Main disc, centred in XY, resting on z = 0
    cylinder(d = disc_d, h = disc_h);

    // Magnet pockets cut from top face
    for (i = [0 : mag_count - 1]) {
        a = mag_start_ang + i * 360 / mag_count;
        translate([ (mag_circle_d / 2) * cos(a),
                    (mag_circle_d / 2) * sin(a),
                    disc_h - mag_depth ])
            cylinder(d = mag_d, h = mag_depth + eps);
    }

    // Through hole for motor shaft
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = disc_h + 2 * eps);
}
