// Tubing reel - printed lying on the bottom flange
$fn = 128;

// --- Dimensions (mm) ---
flange_d      = 50;   // flange diameter
flange_t      = 2;    // flange thickness
core_d        = 20;   // core diameter
core_h        = 22;   // core height (z = 2 to z = 32)
bore_d        = 6;    // central through-bore diameter
eps           = 0.5;  // cutter overshoot

total_h = flange_t + core_h + flange_t;  // 34 mm

difference() {
    union() {
        // Bottom flange: z = 0 to 2
        cylinder(d = flange_d, h = flange_t);
        // Core: z = 2 to 32 (slight overlap into flanges for a clean union)
        translate([0, 0, flange_t - 0.01])
            cylinder(d = core_d, h = core_h + 0.02);
        // Top flange: z = 32 to 34
        translate([0, 0, flange_t + core_h])
            cylinder(d = flange_d, h = flange_t);
    }
    // Central bore through all
    translate([0, 0, -eps])
        cylinder(d = bore_d, h = total_h + 2 * eps);
}
