// arm. NOVEL general structural part.
//

arm   = 33.2;
wide  = 29.3;
t     = 7.6;
screw = 5.7;

$fn = 48;

g  = arm * 0.7;         // brace leg length
ov = min(t * 0.6, 2);   // dig the brace into both arms so the union is manifold (no coplanar faces)

difference() {
    union() {
        cube([arm, wide, t]);          // horizontal arm
        cube([t, wide, arm]);          // vertical arm
        translate([0, wide, 0]) rotate([90, 0, 0])
            linear_extrude(wide) polygon([[t - ov, t - ov], [g, t - ov], [t - ov, g]]);   // diagonal brace
    }
    translate([arm * 0.72, wide / 2, -1]) cylinder(h = t + 2, d = screw);
    translate([-1, wide / 2, arm * 0.72]) rotate([0, 90, 0]) cylinder(h = t + 2, d = screw);
}
```

```openscad
// Pipe saddle clamp - a block with a semicircular groove that cradles a round pipe or
// rod against a flat surface, with a bolt hole each side to screw it down. NOVEL part.
//

pipe_d = 27.6;
bolt_d = 7;
base_t = 8.88;

$fn = 72;

sr     = pipe_d / 2 + 0.5;          // groove radius, with a little clearance
L      = 16;                        // length along the pipe axis
margin = bolt_d + 4;
w      = pipe_d + 2 * margin;       // overall width
h      = base_t + sr;               // block height so the groove centre sits at the top

difference() {
    translate([-w / 2, -L / 2, 0]) cube([w, L, h]);
    translate([0, -L / 2 - 1, h]) rotate([-90, 0, 0]) cylinder(h = L + 2, r = sr);   // groove
    for (x = [-(pipe_d / 2 + margin / 2), pipe_d / 2 + margin / 2])
        translate([x, 0, -1]) cylinder(h = h + 2, d = bolt_d);                        // bolt holes
}
```

