// Diffuser sheet frame for lab light pad
// Print orientation: flat on bed, centred on origin

$fn = 64;

// --- Dimensions (mm) ---
frame_x      = 180;   // outer length (X)
frame_y      = 68;    // outer width (Y)
frame_t      = 5;     // frame thickness (Z)
window_x     = 156;   // window length (X)
window_y     = 66;    // window width (Y)
hole_d       = 4.5;   // corner through-hole diameter
hole_x       = 84;    // hole centre offset from origin in X (±)
hole_y       = 39;    // hole centre offset from origin in Y (±)
eps          = 0.5;   // cut overshoot to avoid coplanar faces

difference() {
    // Frame body
    translate([-frame_x/2, -frame_y/2, 0])
        cube([frame_x, frame_y, frame_t]);

    // Central window
    translate([-window_x/2, -window_y/2, -eps])
        cube([window_x, window_y, frame_t + 2*eps]);

    // Corner through-holes
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx * hole_x, sy * hole_y, -eps])
            cylinder(d = hole_d, h = frame_t + 2*eps, $fn = 64);
}
```

