// Adjustable shim plate with two rounded-end bolt slots
// Units: mm

// ---- Plate ----
plate_len   = 50;    // X length
plate_wid   = 27;    // Y width
plate_thk   = 4;     // Z thickness

// ---- Slots ----
slot_w      = 3.4;   // slot width (also end diameter)
slot_len    = 18;    // slot overall length, end to end
slot_xs     = [-11, 11]; // slot centre X positions
slot_y      = 0;     // slot centre Y position

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces
$fn         = 64;    // curve resolution

// Rounded-end slot (stadium) cutter centred at origin, running along X
module slot_cutter(w, l, h) {
    c = (l - w) / 2; // distance from slot centre to end-circle centres
    translate([0, 0, -eps])
        hull() {
            for (sx = [-c, c])
                translate([sx, 0, 0])
                    cylinder(d = w, h = h + 2 * eps, $fn = 64);
        }
}

difference() {
    // Plate body, centred in X/Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Through-slots
    for (x = slot_xs)
        translate([x, slot_y, 0])
            slot_cutter(slot_w, slot_len, plate_thk);
}
```

