// Adjustable shim plate with two rounded-end bolt slots
// Print orientation: flat on bed, z = 0 to plate_t

// ---------- Parameters ----------
plate_l   = 50;    // plate length along X (mm)
plate_w   = 28;    // plate width along Y (mm)
plate_t   = 2;     // plate thickness along Z (mm)

slot_w    = 5.5;   // slot width (mm) = end-round diameter
slot_len  = 10;    // slot overall length, end to end (mm)
slot_xs   = [-14, 14]; // slot centre X positions (mm)
slot_y    = 0;     // slot centre Y position (mm)

eps       = 0.5;   // cutter overshoot past plate faces (mm)
$fn       = 96;    // curve resolution

// ---------- Derived ----------
slot_r    = slot_w / 2;              // end radius
slot_cc   = slot_len - slot_w;       // centre-to-centre distance of end arcs

// ---------- Modules ----------
module slot_cutter(len, w, h) {
    // Stadium-shaped cutter centred on origin, running along X
    translate([0, 0, -eps])
        hull() {
            for (sx = [-1, 1])
                translate([sx * (len - w) / 2, 0, 0])
                    cylinder(d = w, h = h + 2 * eps, $fn = 96);
        }
}

// ---------- Model ----------
difference() {
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    for (x = slot_xs)
        translate([x, slot_y, 0])
            slot_cutter(slot_len, slot_w, plate_t);
}
