// Glassware drying board: base plate with a 3 x 2 grid of vertical pegs

// ---------- Parameters ----------
plate_x      = 90;    // base plate length (X)
plate_y      = 55;    // base plate width (Y)
plate_t      = 5;     // base plate thickness (z = 0 to 5)

peg_d        = 8;     // peg diameter
peg_top_z    = 45;    // peg top height (absolute Z)
peg_h        = peg_top_z - plate_t;  // peg height above plate (40 mm)

peg_nx       = 5;     // pegs along X
peg_ny       = 2;     // pegs along Y
peg_pitch_x  = 35;    // centre-to-centre spacing along X
peg_pitch_y  = 35;    // centre-to-centre spacing along Y

overlap      = 0.01;  // small embed of pegs into plate for a clean union

$fn = 64;

// ---------- Model ----------
union() {
    // Base plate, centred in XY, resting on z = 0
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Peg grid, centred on the plate
    for (i = [0 : peg_nx - 1])
        for (j = [0 : peg_ny - 1])
            translate([(i - (peg_nx - 1)/2) * peg_pitch_x,
                       (j - (peg_ny - 1)/2) * peg_pitch_y,
                       plate_t - overlap])
                cylinder(d = peg_d, h = peg_h + overlap);
}
