// Divider insert for sample storage box - open 3x3 lattice, no floor
// Print orientation: stands on the bed (z = 0), centred on origin in X/Y

outer_x   = 60;    // outer wall size along X (mm)
outer_y   = 72;    // outer wall size along Y (mm)
height    = 20;    // wall height (mm)
wall      = 1.5;   // thickness of all walls, outer and inner (mm)
cells_x   = 3;     // number of cells along X
cells_y   = 3;     // number of cells along Y
cell      = 18;    // inside size of each square cell (mm)
eps       = 0.5;   // cutter overshoot past top/bottom faces (mm)

pitch     = cell + wall;   // centre-to-centre spacing of cells (19.5 mm)

// Check: cells_x*cell + (cells_x+1)*wall = 3*18 + 4*1.5 = 60 mm (matches outer_x)

difference() {
    // Solid outer block
    translate([-outer_x/2, -outer_y/2, 0])
        cube([outer_x, outer_y, height]);

    // Cut out the open cells (through top and bottom - no floor)
    for (i = [0 : cells_x - 1])
        for (j = [0 : cells_y - 1])
            translate([(i - (cells_x - 1)/2) * pitch - cell/2,
                       (j - (cells_y - 1)/2) * pitch - cell/2,
                       -eps])
                cube([cell, cell, height + 2*eps]);
}
