// Adjustable shim plate with two rounded-end bolt slots
// Units: mm

// ---------- Plate ----------
plate_length    = 50;    // X dimension
plate_width     = 28;    // Y dimension
plate_thickness = 3;     // Z dimension (print height)

// ---------- Slots ----------
slot_width      = 4.59;   // slot width (equal to end radius x 2)
slot_length     = 18;    // overall slot length, end to end
slot_centres_x  = [-11, 11]; // slot centre X positions
slot_centre_y   = 0;     // slot centre Y position

// ---------- Misc ----------
eps  = 0.5;              // cutter overshoot past top/bottom faces
$fn  = 64;               // curve resolution

// Distance between the two end-circle centres of a slot
slot_c2c = slot_length - slot_width;

module slot_cutter() {
    translate([0, 0, -eps])
        linear_extrude(height = plate_thickness + 2 * eps)
            hull() {
                for (sx = [-slot_c2c / 2, slot_c2c / 2])
                    translate([sx, 0])
                        circle(d = slot_width, $fn = 64);
            }
}

difference() {
    // Plate body, centred in XY, resting on z = 0
    translate([-plate_length / 2, -plate_width / 2, 0])
        cube([plate_length, plate_width, plate_thickness]);

    // Through-slots
    for (x = slot_centres_x)
        translate([x, slot_centre_y, 0])
            slot_cutter();
}
