// Spur gear (simplified teeth) - a flat gear with a hub and a central bore. The teeth are a
// trapezoidal approximation (not a true involute) but they print and mesh for light use.
// NOVEL general mechanical part.
//

teeth = 32;
mod   = 1;
thick = 5.9;
bore  = 3.2;

$fn = 96;

