// Hex key organiser block
// Units: mm

// ---- Block dimensions ----
block_l = 64;      // length along X
block_w = 12;      // width along Y
block_h = 20;      // height along Z

// ---- Pocket parameters ----
pocket_depth   = 12;                        // depth from top face
pocket_pitch   = 10;                        // centre-to-centre spacing along X
pocket_flats   = [3.4, 4.4, 5.4, 6.4, 8.4]; // across-flats sizes, -X to +X
pocket_count   = len(pocket_flats);
overcut        = 0.5;                       // extension past the top face

// Across-flats -> circumradius for a regular hexagon
function hex_r(f) = f / sqrt(3);

difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_l/2, -block_w/2, 0])
        cube([block_l, block_w, block_h]);

    // Hexagonal pockets along y = 0, centred on the block.
    // cylinder with $fn=6 puts a vertex on +X, so two flats are parallel to X.
    for (i = [0 : pocket_count - 1]) {
        x = (i - (pocket_count - 1) / 2) * pocket_pitch;
        translate([x, 0, block_h - pocket_depth])
            cylinder(r = hex_r(pocket_flats[i]),
                     h = pocket_depth + overcut,
                     $fn = 6);
    }
}
```

