// Wall mounting strip with 3 countersunk screw holes
// Print orientation: flat on bed, countersinks facing up (+Z)

// ---------- Dimensions ----------
bar_length   = 84;    // bar length along X
bar_width    = 24;    // bar width along Y
bar_thick    = 8;     // bar thickness along Z

hole_count   = 3;     // number of screw holes
hole_pitch   = 30;    // centre-to-centre spacing along X
hole_d       = 5.5;   // through-hole diameter
csk_d        = 11;    // countersink diameter at top surface
csk_angle    = 90;    // countersink included angle (degrees)

eps          = 0.5;   // overshoot for clean cuts
$fn          = 96;    // curve resolution

// ---------- Derived ----------
csk_depth = (csk_d - hole_d) / 2 / tan(csk_angle / 2); // = 2.75 mm for 90 deg
x0        = -(hole_count - 1) * hole_pitch / 2;        // first hole X position

// ---------- Model ----------
difference() {
    // Bar
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thick]);

    for (i = [0 : hole_count - 1]) {
        translate([x0 + i * hole_pitch, 0, 0]) {
            // Through-hole
            translate([0, 0, -eps])
                cylinder(h = bar_thick + 2 * eps, d = hole_d);

            // 90-degree countersink, extended above top face along the same cone
            translate([0, 0, bar_thick - csk_depth])
                cylinder(h = csk_depth + eps,
                         r1 = hole_d / 2,
                         r2 = csk_d / 2 + eps * tan(csk_angle / 2));
        }
    }
}
