// Units: mm. Printed resting on XY plane, building up +Z.

// ---------- Parameters ----------
block_x      = 36;    // block length along X
block_y      = 16;    // block depth along Y
block_z      = 27;    // block height along Z

bore_d       = 9;     // horizontal bore diameter (along Y)
bore_x       = 0;     // bore axis X position
bore_z       = 10;    // bore axis Z position

mount_d      = 3.4;   // vertical mounting hole diameter
mount_x      = 13;    // mounting hole X offset (+/-)
mount_y      = 0;     // mounting hole Y position

eps          = 0.5;   // cutter overshoot past faces
$fn          = 96;    // curve resolution

// ---------- Model ----------
difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_z]);

    // Horizontal bore along Y
    translate([bore_x, 0, bore_z])
        rotate([90, 0, 0])
            cylinder(d = bore_d, h = block_y + 2*eps, center = true);

    // Vertical mounting holes through full height
    for (sx = [-1, 1])
        translate([sx * mount_x, mount_y, -eps])
            cylinder(d = mount_d, h = block_z + 2*eps);
}
