```openscad
// Tubing organiser - flat plate with notches along +Y edge
// Units: mm

plate_len   = 72;   // plate length (X)
plate_wid   = 24;   // plate width (Y)
plate_thk   = 6;    // plate thickness (Z)

notch_count = 5;    // number of notches
notch_w     = 4;    // notch width (X)
notch_d     = 10;   // notch depth into plate (along -Y)
notch_pitch = 12;   // centre-to-centre spacing (X)

eps         = 0.5;  // cutter overshoot past faces

$fn = 64;

difference() {
    // Plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Notches cut from the +Y edge, through full thickness
    for (i = [0 : notch_count - 1]) {
        x_c = (i - (notch_count - 1)/2) * notch_pitch;
        translate([x_c - notch_w/2,
                   plate_wid/2 - notch_d,
                   -eps])
            cube([notch_w, notch_d + eps, plate_thk + 2*eps]);
    }
}
