// Bench mat for 3 Petri dishes (90 mm) - prevents sliding
// Print orientation: flat on bed, recesses facing up

// ---- Plate ----
plate_x      = 316;    // plate length along X (mm)
plate_y      = 112;    // plate width along Y (mm)
plate_t      = 5;      // plate thickness (mm)

// ---- Dish recesses ----
recess_d     = 54.9;   // recess diameter (mm)
recess_depth = 3;      // recess depth from top face (mm)
recess_n     = 3;      // number of recesses
recess_pitch = 101.5;  // centre-to-centre spacing along X (mm)

// ---- Misc ----
eps          = 0.5;    // overcut past faces to avoid coplanar surfaces
$fn          = 128;    // circle resolution

difference() {
    // Base plate, centred in XY, sitting on z = 0
    translate([-plate_x / 2, -plate_y / 2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Row of circular recesses cut into the top face, centred on the plate
    for (i = [0 : recess_n - 1]) {
        x = (i - (recess_n - 1) / 2) * recess_pitch;
        translate([x, 0, plate_t - recess_depth])
            cylinder(d = recess_d, h = recess_depth + eps, $fn = 128);
    }
}
