```openscad
// Flat hex-cap wrench for reagent bottles
// Print orientation: flat on the bed, z = 0 to plate_t

// ---------------- Parameters ----------------
plate_t      = 5;    // plate thickness (Z)
head_d       = 50;   // round head diameter, centred on origin
handle_w     = 10;   // handle width (Y), centred on y = 0
handle_x0    = 0;    // handle start (X)
handle_x1    = 90;   // handle end (X)
hex_af       = 22;   // hex hole size across flats
eps          = 0.5;  // cutter overshoot past faces

$fn = 128;           // smoothness of round head

// Derived
hex_r = (hex_af / 2) / cos(30);  // hex circumradius (centre to vertex)

// ---------------- Model ----------------
difference() {
    union() {
        // Round head
        cylinder(d = head_d, h = plate_t);

        // Straight handle bar
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, plate_t]);
    }

    // Hexagonal hole: circle($fn=6) puts vertices on the X axis,
    // so the top and bottom flats are parallel to X.
    translate([0, 0, -eps])
        linear_extrude(height = plate_t + 2 * eps)
            circle(r = hex_r, $fn = 6);
}
```

