// DIY syringe pump end block
// Print orientation: block rests on XY plane, builds up +Z

// ---------- Parameters ----------
block_x      = 24;    // block length along X
block_y      = 16;    // block depth along Y
block_z      = 20;    // block height along Z

bore_d       = 10;    // horizontal through-bore diameter (along Y)
bore_x       = 0;     // bore axis X position
bore_z       = 10;    // bore axis Z height

mount_d      = 4.5;   // vertical mounting hole diameter
mount_x      = 15;    // mounting holes at x = +/- mount_x
mount_y      = 0;     // mounting hole Y position

eps          = 0.5;   // cutter overshoot past faces

$fn = 96;             // curve resolution

// ---------- Model ----------
difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_z]);

    // Horizontal bore along Y
    translate([bore_x, -block_y/2 - eps, bore_z])
        rotate([-90, 0, 0])
            cylinder(d = bore_d, h = block_y + 2*eps);

    // Vertical mounting holes through full height
    for (sx = [-1, 1])
        translate([sx * mount_x, mount_y, -eps])
            cylinder(d = mount_d, h = block_z + 2*eps);
}
