notch_width  = 7;     // notch width along X
notch_depth  = 14;    // notch depth into plate along -Y
notch_pitch  = 15;    // centre-to-centre spacing along X

eps = 0.5;            // overcut so cuts pass cleanly through faces

$fn = 64;

difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_length/2, -plate_width/2, 0])
        cube([plate_length, plate_width, plate_thick]);

    // Notches along +Y edge, centred along X
    for (i = [0 : notch_count - 1]) {
        x_c = (i - (notch_count - 1)/2) * notch_pitch;
        translate([x_c - notch_width/2,
                   plate_width/2 - notch_depth,
                   -eps])
            cube([notch_width,
                  notch_depth + eps,
                  plate_thick + 2*eps]);
    }
}
