// Hex key organiser block
// Units: mm

// ---- Block dimensions ----
block_len   = 70;    // X length
block_wid   = 18;    // Y width
block_ht    = 34;    // Z height

// ---- Pocket parameters ----
pocket_depth = 15;                        // depth from top face
pocket_pitch = 12;                        // centre-to-centre spacing along X
pocket_flats = [2.9, 3.4, 4.4, 5.4, 6.4]; // across-flats sizes, -X to +X
n_pockets    = len(pocket_flats);         // number of pockets

eps = 0.5;   // overshoot for clean cuts

// Circumradius of a hexagon from its across-flats size
function hex_r(f) = f / sqrt(3);

difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Hexagonal pockets along the X axis (y = 0)
    for (i = [0 : n_pockets - 1]) {
        x = (i - (n_pockets - 1) / 2) * pocket_pitch;
        // $fn = 6 places vertices on the X axis, so two flats are parallel to X
        translate([x, 0, block_ht - pocket_depth])
            cylinder(h = pocket_depth + eps, r = hex_r(pocket_flats[i]), $fn = 6);
    }
}
```

