// Glassware drying board - base plate with 5 x 2 grid of vertical pegs
// Print orientation: plate flat on bed, pegs pointing up (+Z)

// ---------- Parameters ----------
plate_x      = 184;   // base plate length (X)
plate_y      = 64;    // base plate width (Y)
plate_t      = 4;     // base plate thickness (z = 0 to 4)

peg_d        = 8;     // peg diameter
peg_top_z    = 34;    // peg top height (absolute Z)
peg_h        = peg_top_z - plate_t;  // peg height above plate (30 mm)
peg_overlap  = 0.5;   // peg sinks into plate for a solid union

peg_nx       = 5;     // number of pegs along X
peg_ny       = 2;     // number of pegs along Y
peg_pitch_x  = 64;    // centre-to-centre spacing along X
peg_pitch_y  = 40;    // centre-to-centre spacing along Y

$fn = 64;             // curve resolution

// ---------- Model ----------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Peg grid, centred on the plate
    for (i = [0 : peg_nx - 1])
        for (j = [0 : peg_ny - 1])
            translate([(i - (peg_nx - 1)/2) * peg_pitch_x,
                       (j - (peg_ny - 1)/2) * peg_pitch_y,
                       plate_t - peg_overlap])
                cylinder(d = peg_d, h = peg_h + peg_overlap, $fn = 64);
}
