peg_top_z = 41;     // top of pegs
peg_h = peg_top_z - plate_t; // peg height above plate (30)
peg_nx = 3;         // pegs along X
peg_ny = 2;         // pegs along Y
peg_pitch = 40;     // centre-to-centre spacing (both directions)
overlap = 0.5;      // peg sinks into plate for a solid union

union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Peg grid, centred on plate
    for (i = [0 : peg_nx - 1])
        for (j = [0 : peg_ny - 1])
            translate([(i - (peg_nx - 1)/2) * peg_pitch,
                       (j - (peg_ny - 1)/2) * peg_pitch,
                       plate_t - overlap])
                cylinder(d = peg_d, h = peg_h + overlap);
}
