            translate([fillet, 0, fillet]) rotate([-90, 0, 0]) cylinder(h = w, r = fillet);
        }
    }
    translate([leg * 0.7, w / 2, -1]) cylinder(h = t + 2, d = hole);                      // horizontal hole
    translate([-1, w / 2, leg * 0.7]) rotate([0, 90, 0]) cylinder(h = t + 2, d = hole);   // vertical hole
}
