// Horizontal pipette rest
$fn = 96;

// --- Dimensions ---
base_len    = 120;  // base plate length (X)
base_wid    = 35;   // base plate width (Y)
base_th     = 5;    // base plate thickness (Z)
upright_th  = 8;    // upright thickness in X
upright_h   = 30;   // upright total height from bed (Z)
notch_r     = 7;    // cradle notch radius
eps         = 0.5;  // overcut for clean differences

difference() {
    union() {
        // Base plate
        translate([-base_len/2, -base_wid/2, 0])
            cube([base_len, base_wid, base_th]);

        // Uprights at each end, flush with plate ends
        for (sx = [-1, 1])
            translate([sx > 0 ? base_len/2 - upright_th : -base_len/2,
                       -base_wid/2, 0])
                cube([upright_th, base_wid, upright_h]);
    }

    // Semicircular cradle notches, axis along X, centre at y=0, z=upright_h
    for (sx = [-1, 1])
        translate([sx * (base_len/2 - upright_th/2), 0, upright_h])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = upright_th + 2*eps, center = true);
}
