// Tubing reel - printed lying on bottom flange
$fn = 128;

flange_d   = 80;   // flange diameter
flange_t   = 3;    // flange thickness
core_d     = 26;   // core diameter
core_h     = 20;   // core height (z = 3 to z = 23)
bore_d     = 6;    // central bore diameter
overlap    = 0.01; // overlap for clean unions
cut_ext    = 0.5;  // bore extension past faces

total_h = flange_t + core_h + flange_t; // 26

difference() {
    union() {
        // bottom flange z = 0..3
        cylinder(d = flange_d, h = flange_t);
        // core z = 3..23 (slight overlap into flanges)
        translate([0, 0, flange_t - overlap])
            cylinder(d = core_d, h = core_h + 2 * overlap);
        // top flange z = 23..26
        translate([0, 0, flange_t + core_h])
            cylinder(d = flange_d, h = flange_t);
    }
    // central bore through full height
    translate([0, 0, -cut_ext])
        cylinder(d = bore_d, h = total_h + 2 * cut_ext);
}
```

