// Tubing reel - printed lying on the bottom flange
$fn = 128;

flange_d   = 70;   // flange diameter
flange_t   = 4;    // flange thickness
core_d     = 25;   // core diameter
core_h     = 15;   // core height (z = 3 to z = 18)
bore_d     = 6;    // central bore diameter
overlap    = 0.01; // small overlap for union between parts
cut_ext    = 0.5;  // bore extension past faces

total_h = flange_t + core_h + flange_t; // 21

difference() {
    union() {
        // bottom flange z = 0..3
        cylinder(d = flange_d, h = flange_t);
        // core z = 3..18 (slightly overlapping flanges)
        translate([0, 0, flange_t - overlap])
            cylinder(d = core_d, h = core_h + 2 * overlap);
        // top flange z = 18..21
        translate([0, 0, flange_t + core_h])
            cylinder(d = flange_d, h = flange_t);
    }
    // central through bore
    translate([0, 0, -cut_ext])
        cylinder(d = bore_d, h = total_h + 2 * cut_ext);
}
