// Syringe pump end block
// Print orientation: block resting on XY plane at z = 0, centred in X and Y.

// ---------------- Parameters ----------------
block_x      = 40;    // block length along X (mm)
block_y      = 19;    // block depth along Y (mm)
block_z      = 28;    // block height along Z (mm)

bore_d       = 8;     // horizontal bore diameter (through along Y) (mm)
bore_x       = 0;     // bore axis X position (mm)
bore_z       = 14;    // bore axis height (mm)

mount_d      = 4.5;   // vertical mounting hole diameter (mm)
mount_xs     = [-14, 14]; // mounting hole X positions (mm)
mount_y      = 0;     // mounting hole Y position (mm)

eps          = 0.5;   // extra length on cutters to avoid coplanar faces (mm)
$fn          = 96;    // circle resolution

// ---------------- Model ----------------
difference() {
    // Main block
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_z]);

    // Horizontal bore along Y
    translate([bore_x, 0, bore_z])
        rotate([90, 0, 0])
            cylinder(d = bore_d, h = block_y + 2*eps, center = true);

    // Vertical mounting holes through full height
    for (mx = mount_xs)
        translate([mx, mount_y, -eps])
            cylinder(d = mount_d, h = block_z + 2*eps);
}
```

