slot_y      = 0;     // slot centre Y position

// ---------- Cut clearance ----------
eps         = 0.5;   // extra cut depth past top/bottom faces

// Derived
slot_r      = slot_w / 2;               // end radius
slot_cc     = slot_len - slot_w;        // distance between end-circle centres

// 2D stadium-shaped slot outline, centred on origin, running along X
module slot_2d() {
    hull() {
        for (s = [-1, 1])
            translate([s * slot_cc / 2, 0]) circle(r = slot_r);
    }
}

difference() {
    // Plate body
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Through-slots
    for (x = slot_xs)
        translate([x, slot_y, -eps])
            linear_extrude(height = plate_thk + 2 * eps)
                slot_2d();
}
