// Flat spacer ring - raises an instrument off the bench
// Units: mm. Prints flat on the bed (z = 0 upward), centred on origin.

// ---------------- Parameters ----------------
ring_thickness   = 3;     // ring height (Z)
outer_diameter   = 90;    // outer diameter of annulus
inner_diameter   = 66;    // inner (bore) diameter of annulus
hole_count       = 4;     // number of mounting through-holes
hole_diameter    = 4.675;   // through-hole diameter
hole_pcd         = 78;    // pitch-circle diameter of holes
hole_start_angle = 0;     // first hole on +X axis (degrees)

cut_extra        = 0.5;   // overshoot for clean boolean cuts
$fn              = 128;   // facet count for round features

// ---------------- Model ----------------
difference() {
    // Solid disc
    cylinder(h = ring_thickness, d = outer_diameter);

    // Central bore
    translate([0, 0, -cut_extra])
        cylinder(h = ring_thickness + 2 * cut_extra, d = inner_diameter);

    // Evenly spaced through-holes on the pitch circle
    for (i = [0 : hole_count - 1])
        rotate([0, 0, hole_start_angle + i * 360 / hole_count])
            translate([hole_pcd / 2, 0, -cut_extra])
                cylinder(h = ring_thickness + 2 * cut_extra, d = hole_diameter);
}
