// Glassware drying board: base plate with a 4 x 2 grid of vertical pegs
// Print orientation: base plate flat on the bed, pegs building upward (+Z)

$fn = 64;

// ---- Base plate ----
plate_x      = 125;   // plate length along X (mm)
plate_y      = 55;    // plate width along Y (mm)
plate_t      = 4;     // plate thickness (mm), z = 0 to 4

// ---- Pegs ----
peg_d        = 8;     // peg diameter (mm)
peg_top_z    = 34;    // top of pegs (mm)
peg_h        = peg_top_z - plate_t;  // peg height above plate (30 mm)
peg_nx       = 4;     // number of pegs along X
peg_ny       = 4;     // number of pegs along Y
peg_pitch_x  = 35;    // centre-to-centre spacing along X (mm)
peg_pitch_y  = 35;    // centre-to-centre spacing along Y (mm)
peg_overlap  = 0.5;   // pegs sink this far into the plate for a solid union (mm)

union() {
    // Base plate, centred in X and Y
    translate([-plate_x / 2, -plate_y / 2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Peg grid, centred on the plate
    for (i = [0 : peg_nx - 1])
        for (j = [0 : peg_ny - 1])
            translate([
                (i - (peg_nx - 1) / 2) * peg_pitch_x,
                (j - (peg_ny - 1) / 2) * peg_pitch_y,
                plate_t - peg_overlap
            ])
                cylinder(d = peg_d, h = peg_h + peg_overlap);
}
