// Divider insert for sample storage box - open lattice, no floor
// Print orientation: standing on the bed, open top and bottom

// ---------- Parameters ----------
outer_x   = 158;    // outside size along X (mm)
outer_y   = 40.5;  // outside size along Y (mm)
height    = 20;    // wall height (mm)
wall      = 1.5;   // thickness of all walls, outer and inner (mm)
cells_x   = 5;     // number of cells along X
cells_y   = 2;     // number of cells along Y
cell      = 18;    // inside size of each square cell (mm)
eps       = 0.5;   // overshoot for clean cuts (mm)

// Check: cells_x*cell + (cells_x+1)*wall = 99
//        cells_y*cell + (cells_y+1)*wall = 40.5
pitch = cell + wall;  // centre-to-centre spacing of cells

// ---------- Model ----------
difference() {
    // Solid block that becomes the lattice
    translate([-outer_x/2, -outer_y/2, 0])
        cube([outer_x, outer_y, height]);

    // Open cells cut straight through (no floor)
    for (i = [0 : cells_x - 1])
        for (j = [0 : cells_y - 1])
            translate([-outer_x/2 + wall + i * pitch,
                       -outer_y/2 + wall + j * pitch,
                       -eps])
                cube([cell, cell, height + 2 * eps]);
}
