// Cuvette stand for 6 standard 1 cm spectrophotometer cuvettes
// Print orientation: base on XY plane (z = 0), pockets open upward

// ---------- Block dimensions ----------
block_x = 128;      // block length along X
block_y = 28;       // block width along Y
block_h = 28;       // block height (Z)

// ---------- Pocket dimensions ----------
