pocket_w     = 13;  // pocket size in X and Y (square)
pocket_depth = 34;  // pocket depth from top face
pocket_pitch = 20;  // centre-to-centre spacing along X
floor_t      = block_h - pocket_depth; // remaining floor thickness (3 mm)

// ---------- Cutting overshoot ----------
eps = 0.5;          // extension past the top face to avoid coplanar faces

$fn = 64;

// X position of the first pocket so the row is centred on the block
first_x = -(pocket_n - 1) * pocket_pitch / 2;

difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square pockets opened from the top
    for (i = [0 : pocket_n - 1]) {
        translate([first_x + i * pocket_pitch - pocket_w / 2,
                   -pocket_w / 2,
                   floor_t])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
    }
}
