// Adjustable shim plate with two rounded-end bolt slots
// Print orientation: flat on the bed, z = 0 upward

// ---- Plate dimensions ----
plate_length    = 80;    // overall length along X
plate_width     = 32;    // overall width along Y
plate_thickness = 2;     // thickness along Z

// ---- Slot dimensions ----
slot_width      = 4.5;   // slot width (Y), equals end diameter
slot_length     = 12;    // slot overall length end to end (X)
slot_positions  = [-18, 18]; // slot centre X positions (y = 0)

// ---- Cut clearance ----
cut_extra       = 0.5;   // extension of cutters past faces

$fn = 96;

slot_straight = slot_length - slot_width; // centre-to-centre of end arcs

module slot_cutter() {
    translate([0, 0, -cut_extra])
        hull() {
            for (dx = [-slot_straight / 2, slot_straight / 2])
                translate([dx, 0, 0])
                    cylinder(d = slot_width, h = plate_thickness + 2 * cut_extra);
        }
}

difference() {
    translate([-plate_length / 2, -plate_width / 2, 0])
        cube([plate_length, plate_width, plate_thickness]);

    for (x = slot_positions)
        translate([x, 0, 0])
            slot_cutter();
}
