// Microplate riser
// Units: mm. Prints upright: legs on the bed (z = 0), top plate at z = 36..40.

// ---- Top plate ----
plate_x     = 140;   // plate length (X)
plate_y     = 90;    // plate width (Y)
plate_t     = 4;     // plate thickness
plate_top_z = 40;    // z of the plate's top face

// ---- Legs ----
leg_size    = 10;    // square leg cross-section (X and Y)

// ---- Central window ----
window_x    = 100;   // window length (X)
window_y    = 50;    // window width (Y)

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past cut faces
overlap     = 0.01;  // small overlap so legs fuse with plate

// Derived
plate_bot_z = plate_top_z - plate_t;   // underside of plate (36)

union() {
    // Top plate with central window
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bot_z])
            cube([plate_x, plate_y, plate_t]);
        translate([-window_x/2, -window_y/2, plate_bot_z - eps])
            cube([window_x, window_y, plate_t + 2*eps]);
    }

    // Four corner legs, flush with the plate's outer edges
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
                   sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
                   0])
            cube([leg_size, leg_size, plate_bot_z + overlap]);
}
