// Wall mounting strip with countersunk screw holes
// Print orientation: flat on the bed, countersinks facing up (+Z)

$fn = 64;

// ---- Bar dimensions ----
bar_length    = 190;   // X length of the bar
bar_width     = 20;    // Y width of the bar
bar_thickness = 6;     // Z thickness of the bar

// ---- Hole pattern ----
hole_count    = 5;     // number of screw holes
hole_pitch    = 54;    // centre-to-centre spacing along X
hole_d        = 3.4;   // through-hole diameter
csk_d         = 6.5;   // countersink diameter at top surface
csk_angle     = 90;    // countersink included angle (degrees)

// ---- Derived values ----
csk_depth = (csk_d - hole_d) / 2 / tan(csk_angle / 2);  // countersink depth (1.55 mm at 90 deg)
eps       = 0.5;       // overshoot for clean boolean cuts
csk_top_d = csk_d + 2 * eps * tan(csk_angle / 2);       // cone diameter at overshoot height (keeps 90 deg)
first_x   = -(hole_count - 1) * hole_pitch / 2;         // X position of first hole

difference() {
    // Flat bar, centred in X and Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thickness]);

    for (i = [0 : hole_count - 1]) {
        translate([first_x + i * hole_pitch, 0, 0]) {
            // Through-hole
            translate([0, 0, -eps])
                cylinder(d = hole_d, h = bar_thickness + 2 * eps);

            // 90-degree countersink on the top face
            translate([0, 0, bar_thickness - csk_depth])
                cylinder(d1 = hole_d, d2 = csk_top_d, h = csk_depth + eps);
        }
    }
}
