// Stand for 6 standard 1 cm spectrophotometer cuvettes
// Print orientation: flat on bed, pockets opening upward

// ---- Block ----
block_x = 124;      // block length (X)
block_y = 28;       // block width (Y)
block_z = 30;       // block height (Z)

// ---- Pockets ----
pocket_count = 6;       // number of cuvette pockets
pocket_w     = 13.2;    // pocket size in X and Y (square)
pocket_depth = 27;      // pocket depth from top face
pocket_pitch = 23.04;    // centre-to-centre spacing along X
floor_t      = block_z - pocket_depth;  // = 3 mm floor below pockets

// ---- Misc ----
eps = 0.5;          // cutter overshoot past top face

difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_z]);

    // Row of square pockets, centred on the block
    for (i = [0 : pocket_count - 1]) {
        px = (i - (pocket_count - 1)/2) * pocket_pitch;
        translate([px - pocket_w/2, -pocket_w/2, floor_t])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
    }
}
