// Hex key organiser block
// Print orientation: block standing on XY plane, pockets open upward (+Z)

// ---------------- Parameters ----------------
block_len   = 84;    // block length along X (mm)
block_wid   = 18;    // block width along Y (mm)
block_ht    = 20;    // block height along Z (mm)

pocket_depth = 11;   // depth of hex pockets from top face (mm)
pocket_pitch = 12;   // centre-to-centre spacing of pockets along X (mm)
pocket_flats = [2.9, 3.4, 4.4, 5.4, 6.4, 8.4]; // across-flats sizes, -X to +X (mm)

overcut = 0.5;       // extra cutter length past the top face (mm)

n_pockets = len(pocket_flats);

// ---------------- Helpers ----------------
// Hexagonal prism sized by across-flats distance.
// cylinder with $fn=6 places a vertex on +X, so two flats are parallel to X.
module hex_prism(flats, h) {
    r = flats / sqrt(3);   // circumradius = flats / (2*cos(30))
    cylinder(r = r, h = h, $fn = 6);
}

// ---------------- Model ----------------
difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Hexagonal pockets along the X axis (y = 0)
    for (i = [0 : n_pockets - 1]) {
        x = (i - (n_pockets - 1) / 2) * pocket_pitch;
        translate([x, 0, block_ht - pocket_depth])
            hex_prism(pocket_flats[i], pocket_depth + overcut);
    }
}
```

