// Bench mat for 2 x 60 mm Petri dishes
// Units: mm. Print orientation: flat on bed, top face up.

// ---------- Plate ----------
plate_x      = 148;   // plate length (X)
plate_y      = 78;    // plate width (Y)
plate_t      = 5;     // plate thickness (Z)

// ---------- Recesses ----------
recess_d     = 61;    // recess diameter (60 mm dish + clearance)
recess_depth = 2;     // recess depth from top face
recess_n     = 2;     // number of recesses in the row
recess_pitch = 114;    // centre-to-centre spacing along X

// ---------- Misc ----------
eps          = 0.5;   // cutter overshoot past top face
$fn          = 128;   // circle resolution

difference() {
    // Plate, centred in X/Y, resting on z = 0
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Row of recesses, centred on the plate
    for (i = [0 : recess_n - 1]) {
        x = (i - (recess_n - 1)/2) * recess_pitch;
        translate([x, 0, plate_t - recess_depth])
            cylinder(d = recess_d, h = recess_depth + eps);
    }
}
