// Divider insert for sample storage box: open lattice, no floor
// 3 x 4 grid of open square cells, all walls 1.5 mm thick

$fn = 64;

// ---------- Dimensions (mm) ----------
outer_x   = 82;      // outside size along X
outer_y   = 127.5;   // outside size along Y
height    = 30;      // wall height
wall      = 1.5;     // thickness of all walls (outer and inner)
cell      = 30;      // inside size of each square cell
cells_x   = 3;       // number of cells along X
cells_y   = 4;       // number of cells along Y
eps       = 0.5;     // cutter overshoot past top/bottom faces

// Check: 3*30 + 4*1.5 = 96 ; 4*30 + 5*1.5 = 127.5

// ---------- Model ----------
difference() {
    // Solid block covering the full outer footprint
    translate([-outer_x/2, -outer_y/2, 0])
        cube([outer_x, outer_y, height]);

    // Cut out each open cell (through the full height, no floor)
    for (i = [0 : cells_x - 1])
        for (j = [0 : cells_y - 1])
            translate([
                -outer_x/2 + wall + i * (cell + wall),
                -outer_y/2 + wall + j * (cell + wall),
                -eps
            ])
                cube([cell, cell, height + 2*eps]);
}
