// Bench mat for 3 Petri dishes (55 mm)
// Print orientation: flat on bed, recesses facing up

// ---- Plate ----
plate_x = 208;      // plate length (X)
plate_y = 76;       // plate width (Y)
plate_t = 6;        // plate thickness (Z)

// ---- Recesses ----
