// Bench mat with recesses for 3 Petri dishes (55 mm)
// Print orientation: flat on bed, recesses facing up

// ---- Plate ----
plate_x = 200;       // plate length along X (mm)
plate_y = 72;        // plate width along Y (mm)
plate_t = 5;         // plate thickness (mm)

// ---- Recesses ----
n_recess     = 2;    // number of dish recesses
recess_d     = 56;   // recess diameter (mm)
recess_depth = 3;    // recess depth (mm)
recess_pitch = 64;   // centre-to-centre spacing along X (mm)

// ---- Misc ----
eps = 0.5;           // overcut past faces to avoid coplanar faces
$fn = 128;           // circle resolution

difference() {
    // Base plate, centred in X/Y, sitting on z = 0
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Row of recesses, centred on the plate
    for (i = [0 : n_recess - 1]) {
