// Adjustable shim plate with two rounded-end bolt slots
// Units: mm. Print flat on the bed (z = 0 up to plate_t).

$fn = 64;

// ---- Plate ----
plate_l = 50;     // plate length along X
plate_w = 28;     // plate width along Y
plate_t = 3;      // plate thickness (Z)

// ---- Slots ----
slot_w   = 5.5;   // slot width (also end-radius diameter)
slot_len = 12;    // slot overall length, end to end along X
slot_xs  = [-12, 12]; // slot centre X positions
slot_y   = 0;     // slot centre Y position

// ---- Cutting clearance ----
eps = 0.5;        // extension past faces to avoid coplanar surfaces

// Derived
slot_r      = slot_w / 2;               // end radius
slot_centre = slot_len - slot_w;        // distance between end-circle centres

// Single through-slot cutter (stadium shape), centred at origin in XY
module slot_cutter() {
    translate([0, 0, -eps])
        linear_extrude(height = plate_t + 2 * eps)
            hull() {
                for (s = [-1, 1])
                    translate([s * slot_centre / 2, 0])
                        circle(r = slot_r);
            }
}

difference() {
    // Plate body, centred in XY, resting on z = 0
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Bolt slots
    for (x = slot_xs)
        translate([x, slot_y, 0])
            slot_cutter();
}
