```openscad
// Hex key organiser block
// Print orientation: block stands on z = 0, pockets open at the top face.

// ---------------- Block dimensions ----------------
block_len    = 58;   // block length along X (mm)
block_wid    = 16;   // block width along Y (mm)
block_h      = 27;   // block height along Z (mm)

// ---------------- Pocket parameters ----------------
pocket_depth = 15;                    // pocket depth from top face (mm)
pocket_pitch = 12;                    // centre-to-centre spacing along X (mm)
pocket_af    = [3.4, 4.4, 5.4, 6.4];  // across-flats sizes, -X to +X (mm)
n_pockets    = len(pocket_af);        // number of pockets

eps          = 0.5;  // cutter overshoot past the top face (mm)

// Convert across-flats to circumradius for a 6-sided cylinder
function af_to_r(af) = af / (2 * cos(30));

// X position of pocket i, row centred on the block
function pocket_x(i) = (i - (n_pockets - 1) / 2) * pocket_pitch;

difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // Hexagonal pockets.
    // A $fn=6 cylinder has vertices at 0°,60°,...: the edges between 60°/120°
    // and 240°/300° are parallel to the X axis, giving two flats parallel to X.
    for (i = [0 : n_pockets - 1])
        translate([pocket_x(i), 0, block_h - pocket_depth])
            cylinder(r = af_to_r(pocket_af[i]),
                     h = pocket_depth + eps,
                     $fn = 6);
}
```

