// Horizontal pipette rest
// Print orientation: base plate on bed (z = 0), uprights build upward (+Z)

$fn = 96;

// ---------- Dimensions (mm) ----------
base_len      = 120;  // base plate length (X)
base_wid      = 30;   // base plate width (Y)
base_thk      = 4;    // base plate thickness (Z)

upright_thk   = 10;   // upright block thickness (X)
upright_h     = 40;   // upright total height from bed (Z)

cradle_r      = 7;    // cradle notch radius
cradle_z      = 40;   // cradle centre height (top edge of upright)
cradle_y      = 0;    // cradle centre Y position

eps           = 0.5;  // overshoot for clean boolean cuts

// ---------- Model ----------
difference() {
    union() {
        // Base plate
        translate([-base_len/2, -base_wid/2, 0])
            cube([base_len, base_wid, base_thk]);

        // Uprights, flush with each end of the plate
        for (sx = [-1, 1])
            translate([sx > 0 ? base_len/2 - upright_thk : -base_len/2,
                       -base_wid/2, 0])
                cube([upright_thk, base_wid, upright_h]);
    }

    // Semicircular cradle notches running along X through each upright
    for (sx = [-1, 1])
        translate([sx * (base_len/2 - upright_thk/2), cradle_y, cradle_z])
            rotate([0, 90, 0])
                cylinder(r = cradle_r, h = upright_thk + 2*eps, center = true);
}
