// Adjustable shim plate with two rounded-end bolt slots
// Units: mm. Print orientation: flat on bed, z = 0 up to plate_t.

// ---------- Plate ----------
plate_l = 60;     // plate length along X
plate_w = 20;     // plate width along Y
plate_t = 4;      // plate thickness (Z)

// ---------- Slots ----------
slot_w     = 4.675;          // slot width (also end-radius diameter)
slot_len   = 16;           // slot overall length, end to end
slot_x     = [-17, 17];    // slot centre X positions
slot_y     = 0;            // slot centre Y position
slot_r     = slot_w / 2;   // end radius
slot_cc    = slot_len - slot_w; // centre-to-centre distance of end arcs

// ---------- Misc ----------
eps = 0.5;        // cutter overshoot past top/bottom faces
$fn = 96;         // curve resolution

// Rounded-end slot cutter, centred at origin, running along X
module slot_cutter() {
    translate([0, 0, -eps])
        hull() {
            for (sx = [-slot_cc / 2, slot_cc / 2])
                translate([sx, 0, 0])
                    cylinder(r = slot_r, h = plate_t + 2 * eps, $fn = 96);
        }
}

difference() {
    // Main plate
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    // Bolt slots
    for (x = slot_x)
        translate([x, slot_y, 0])
            slot_cutter();
}
