// Tubing organiser - flat plate with notches along +Y edge
// Units: mm

$fn = 64;

// Plate dimensions
plate_len   = 50;   // X length
plate_wid   = 32;   // Y width
plate_thk   = 6;    // Z thickness

// Notch parameters
notch_count = 3;    // number of notches
notch_w     = 5;    // notch width along X
notch_d     = 12;   // notch depth into plate along -Y
notch_pitch = 12;   // centre-to-centre spacing along X

// Cut overshoot to avoid coplanar faces
eps = 0.5;

difference() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Notches along +Y edge, centred along X
    for (i = [0 : notch_count - 1]) {
        x_c = (i - (notch_count - 1)/2) * notch_pitch;
        translate([x_c - notch_w/2,
                   plate_wid/2 - notch_d,
                   -eps])
            cube([notch_w, notch_d + eps, plate_thk + 2*eps]);
    }
}
