// Divider insert (open lattice, no floor) for sample storage box
// Print orientation: standing on bed, walls build upward (+Z)

// ---------------- Parameters ----------------
outer_x    = 194;   // outside length along X (mm)
outer_y    = 130;   // outside width along Y (mm)
height     = 27;    // wall height (mm)
wall       = 2;     // thickness of all walls, outer and inner (mm)
cells_x    = 6;     // number of cells along X
cells_y    = 4;     // number of cells along Y
cell       = 30;    // inside size of each square cell (mm)
eps        = 0.5;   // overcut for clean boolean differences (mm)

// Derived: pitch between cell origins
pitch = cell + wall;   // 32 mm

// Sanity check (cells + walls must match the outside size)
assert(abs(cells_x * cell + (cells_x + 1) * wall - outer_x) < 0.001,
       "X dimensions do not add up");
assert(abs(cells_y * cell + (cells_y + 1) * wall - outer_y) < 0.001,
       "Y dimensions do not add up");

// ---------------- Model ----------------
difference() {
    // Solid outer block, centred in X/Y, sitting on z = 0
    translate([-outer_x / 2, -outer_y / 2, 0])
        cube([outer_x, outer_y, height]);

    // Open cells cut straight through (no floor)
    for (i = [0 : cells_x - 1])
        for (j = [0 : cells_y - 1])
            translate([-outer_x / 2 + wall + i * pitch,
                       -outer_y / 2 + wall + j * pitch,
                       -eps])
                cube([cell, cell, height + 2 * eps]);
}
```

