// Adjustable shim plate with two rounded-end bolt slots
// Print orientation: flat on bed, z = 0 to plate_t

// ---------------- Parameters ----------------
plate_l   = 60;    // plate length along X (mm)
plate_w   = 24;    // plate width along Y (mm)
plate_t   = 2;     // plate thickness (mm)

slot_w    = 4.5;   // slot width (mm) = end radius * 2
slot_l    = 18;    // slot overall length, end to end (mm)
slot_xs   = [-11, 11]; // slot centre X positions (mm)
slot_y    = 0;     // slot centre Y position (mm)

eps       = 0.5;   // cutter overshoot past faces (mm)
$fn       = 96;    // curve resolution

// Derived
slot_r    = slot_w / 2;              // end radius
slot_cc   = slot_l - slot_w;         // centre-to-centre distance of slot end arcs

// ---------------- Modules ----------------
module slot_cutter() {
    // Fully rounded slot running along X, extended past top and bottom faces
    translate([0, 0, -eps])
        linear_extrude(height = plate_t + 2 * eps)
            hull() {
                for (s = [-1, 1])
                    translate([s * slot_cc / 2, 0]) circle(r = slot_r);
            }
}

// ---------------- Part ----------------
difference() {
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    for (x = slot_xs)
        translate([x, slot_y, 0]) slot_cutter();
}
