// Wall mounting strip with countersunk screw holes
// Print orientation: flat on bed, countersinks facing up (+Z)

$fn = 96;

// ---------------- Parameters ----------------
bar_length   = 120;   // bar length along X (mm)
bar_width    = 24;    // bar width along Y (mm)
bar_thick    = 4;     // bar thickness along Z (mm)

hole_count   = 3;     // number of screw holes
hole_pitch   = 50;    // centre-to-centre spacing along X (mm)
hole_d       = 4.5;   // through-hole diameter (mm)

cs_d         = 9;     // countersink diameter at top surface (mm)
cs_angle     = 122;    // countersink included angle (degrees)
cs_depth     = (cs_d - hole_d) / 2 / tan(cs_angle / 2); // countersink depth (mm) = 2.25

eps          = 0.5;   // overshoot for clean boolean cuts (mm)

// ---------------- Model ----------------
difference() {
    // Flat bar, centred in X/Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thick]);

    for (i = [0 : hole_count - 1]) {
        x = (i - (hole_count - 1) / 2) * hole_pitch;
        translate([x, 0, 0]) {
            // Through-hole
            translate([0, 0, -eps])
                cylinder(d = hole_d, h = bar_thick + 2 * eps);

            // 90-degree countersink, extended eps above top face
            translate([0, 0, bar_thick - cs_depth])
                cylinder(r1 = hole_d / 2,
                         r2 = cs_d / 2 + eps * tan(cs_angle / 2),
                         h  = cs_depth + eps);
        }
    }
}
