// Flat spacer ring - raises an instrument off the bench
// Prints flat on the bed, centred on the origin.

// ---------- Dimensions (mm) ----------
ring_thickness   = 3;     // height of the annulus (Z)
outer_diameter   = 90;    // outer diameter of ring
inner_diameter   = 62;    // inner (bore) diameter
hole_diameter    = 3.4;   // through-hole diameter
hole_count       = 6;     // number of through-holes
hole_circle_diam = 103;    // bolt circle diameter
first_hole_angle = 0;     // first hole on +X axis (degrees)

// ---------- Modelling parameters ----------
cut_overlap = 0.5;        // cutters extend past faces to avoid coplanar faces
$fn = 128;                // facet count for round features

// ---------- Model ----------
difference() {
    // Solid disc
    cylinder(h = ring_thickness, d = outer_diameter);

    // Central bore
    translate([0, 0, -cut_overlap])
        cylinder(h = ring_thickness + 2 * cut_overlap, d = inner_diameter);

    // Through-holes on the bolt circle
    for (i = [0 : hole_count - 1]) {
        a = first_hole_angle + i * 360 / hole_count;
        translate([hole_circle_diam / 2 * cos(a),
                   hole_circle_diam / 2 * sin(a),
                   -cut_overlap])
            cylinder(h = ring_thickness + 2 * cut_overlap, d = hole_diameter, $fn = 64);
    }
}
