// Flat spacer ring with 3 mounting through-holes
// Print orientation: flat on bed, z = 0 to thickness

$fn = 128;

// --- Dimensions (mm) ---
thickness        = 3;     // ring thickness (Z)
outer_d          = 60;    // outer diameter of annulus
inner_d          = 30;    // inner diameter of annulus
hole_d           = 5.5;   // through-hole diameter
hole_count       = 3;     // number of through-holes
hole_circle_d    = 45;    // bolt circle diameter
hole_start_angle = 0;     // first hole on +X axis (degrees)
eps              = 0.5;   // cutter overshoot past faces

difference() {
    // Main annulus body
    cylinder(d = outer_d, h = thickness);

    // Central bore
    translate([0, 0, -eps])
        cylinder(d = inner_d, h = thickness + 2 * eps);

    // Evenly spaced through-holes on bolt circle
    for (i = [0 : hole_count - 1]) {
        a = hole_start_angle + i * 360 / hole_count;
        translate([hole_circle_d / 2 * cos(a), hole_circle_d / 2 * sin(a), -eps])
            cylinder(d = hole_d, h = thickness + 2 * eps, $fn = 64);
    }
}
