// Bench mat for 2 Petri dishes (55 mm) - anti-slide recesses
// Print orientation: flat on bed, recesses facing up

plate_x      = 140;   // plate length (X)
plate_y      = 74;    // plate width (Y)
plate_t      = 8;     // plate thickness (Z)

recess_d     = 57;    // recess diameter (55 mm dish + clearance)
recess_depth = 5;     // recess depth from top face
recess_n     = 2;     // number of recesses
recess_pitch = 67;    // centre-to-centre spacing along X

eps          = 0.5;   // overcut past top face

$fn = 128;

difference() {
    // base plate, centred in XY, resting on z = 0
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // circular recesses in a single row along X, centred on plate
    for (i = [0 : recess_n - 1]) {
        x = (i - (recess_n - 1)/2) * recess_pitch;
        translate([x, 0, plate_t - recess_depth])
            cylinder(d = recess_d, h = recess_depth + eps);
    }
}
