// Tubing organiser - flat plate with notches along the +Y edge
// Units: mm. Print orientation: flat on bed, z = 0 upward.

// ---------------- Parameters ----------------
plate_len    = 54;   // plate length along X
plate_wid    = 28;   // plate width along Y
plate_thk    = 4;    // plate thickness along Z

notch_count  = 4;    // number of tubing notches
notch_w      = 5;    // notch width along X
notch_depth  = 14;   // notch depth into plate along -Y
notch_pitch  = 11;   // centre-to-centre spacing along X

eps          = 0.5;  // overcut so cutters pass beyond faces

$fn = 64;

// ---------------- Model ----------------
difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Notches along the +Y edge, centred along X
    for (i = [0 : notch_count - 1]) {
        x_c = (i - (notch_count - 1)/2) * notch_pitch;
        translate([x_c - notch_w/2,
                   plate_wid/2 - notch_depth,
                   -eps])
            cube([notch_w, notch_depth + eps, plate_thk + 2*eps]);
    }
}
