// Divider insert for sample storage box - open lattice, no floor
// Print orientation: standing on the bed, walls build upward (+Z)

// ---------------- Parameters ----------------
outer_x   = 128.4;  // outer wall size along X (mm)
outer_y   = 86;     // outer wall size along Y (mm)
height    = 19;     // wall height (mm)
wall      = 1.2;    // thickness of all walls, outer and inner (mm)
cells_x   = 6;      // number of cells along X
cells_y   = 4;      // number of cells along Y
cell      = 20;     // inside size of each square cell (mm)
overcut   = 0.5;    // extra length of cutters past cut faces (mm)

// Check: cells_x*cell + (cells_x+1)*wall = 128.4
//        cells_y*cell + (cells_y+1)*wall = 86
pitch = cell + wall;  // centre-to-centre spacing of cells (mm)

// ---------------- Model ----------------
difference() {
    // Solid outer block, centred on origin in X/Y, resting on z = 0
    translate([-outer_x/2, -outer_y/2, 0])
        cube([outer_x, outer_y, height]);

    // Open cells, cut fully through (no floor)
    for (i = [0 : cells_x - 1])
        for (j = [0 : cells_y - 1])
            translate([-outer_x/2 + wall + i*pitch,
                       -outer_y/2 + wall + j*pitch,
                       -overcut])
                cube([cell, cell, height + 2*overcut]);
}
