// Cuvette stand for 6 standard 1 cm spectrophotometer cuvettes
// Units: mm. Print orientation: base on XY plane, builds +Z.

// ---- Block ----
block_x = 132;      // block length (X)
block_y = 30;       // block width (Y)
block_h = 30;       // block height (Z)

// ---- Pockets ----
n_pockets     = 6;      // number of cuvette pockets
pocket_w      = 13.2;   // pocket size in X and Y (square)
pocket_depth  = 25;     // pocket depth from top face
pocket_pitch  = 12.12;   // centre-to-centre spacing along X
cut_extra     = 0.5;    // overshoot past top face for clean cut

// Derived
floor_t  = block_h - pocket_depth;                 // 5 mm floor below pockets
row_span = (n_pockets - 1) * pocket_pitch;         // first-to-last centre distance

$fn = 64;

difference() {
    // Main block, centred in X/Y, sitting on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square pockets, centred on the block
    for (i = [0 : n_pockets - 1]) {
        translate([-row_span/2 + i * pocket_pitch - pocket_w/2,
                   -pocket_w/2,
                   floor_t])
            cube([pocket_w, pocket_w, pocket_depth + cut_extra]);
    }
}
