// Microplate riser
// Units: mm

// ---- Top plate ----
plate_x     = 140;   // plate length (X)
plate_y     = 100;   // plate width (Y)
plate_t     = 4;     // plate thickness
plate_top_z = 72;    // z of plate top face

// ---- Legs ----
leg_size    = 15;    // square leg side length

// ---- Window ----
win_x       = 90;    // window length (X)
win_y       = 50;    // window width (Y)

// ---- Misc ----
eps         = 0.5;   // cutter overshoot
$fn         = 64;

// Derived
plate_bot_z = plate_top_z - plate_t;   // underside of plate
leg_h       = plate_bot_z;             // legs run from z=0 to underside

union() {
    // Top plate with central window
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bot_z])
            cube([plate_x, plate_y, plate_t]);
        translate([-win_x/2, -win_y/2, plate_bot_z - eps])
            cube([win_x, win_y, plate_t + 2*eps]);
    }

    // Four corner legs, flush with plate outer edges
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
                   sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
                   0])
            cube([leg_size, leg_size, leg_h + 0.01]); // tiny overlap into plate for clean union
}
```

