slot_len = 12;   // slot overall length, end to end, along X
slot_xs  = [-15, 15]; // slot centre X positions
slot_y   = 0;    // slot centre Y position

// ---------- Misc ----------
eps = 0.5;       // cutter overshoot past faces
$fn = 64;        // curve resolution

// Centre-to-centre distance of the slot end arcs
slot_cc = slot_len - slot_w;

module slot_cutter() {
    hull() {
        for (dx = [-slot_cc/2, slot_cc/2])
            translate([dx, 0, -eps])
                cylinder(d = slot_w, h = plate_t + 2*eps, $fn = 64);
    }
}

difference() {
    translate([-plate_l/2, -plate_w/2, 0])
        cube([plate_l, plate_w, plate_t]);

    for (sx = slot_xs)
        translate([sx, slot_y, 0])
            slot_cutter();
}
